#include "mock.h"
#undef MHI_ERR
static char reported[2048];static unsigned reports;
static void report(const char *fmt,...){va_list a;va_start(a,fmt);vsnprintf(reported,sizeof(reported),fmt,a);va_end(a);reports++;}
#define MHI_ERR(d,...) report(__VA_ARGS__)
struct device{int x;};struct mhi_device{struct device dev;};struct mhi_buf{void *buf;dma_addr_t dma_addr;size_t len;};struct image_info{struct mhi_buf *mhi_buf;void *bhi_vec;u32 entries;};struct mhi_controller{struct image_info *rddm_image;struct mhi_device *mhi_dev;};struct rddm_table_info{u64 base_address,actual_phys_address,size;char description[20],file_name[20];};struct rddm_header{u32 version,header_size;struct rddm_table_info table_info[12];};struct file_info{u8 *file_offset;u64 file_size;u32 seg_idx;size_t rem_seg_len;};
/* FUNCTIONS */
int main(void){struct mhi_device dev={0};struct mhi_controller c={.mhi_dev=&dev};unsigned cases=0;size_t hs=8+2*sizeof(struct rddm_table_info);for(size_t prefix=0;prefix<50;prefix++)for(size_t len=1;len<=50;len++){size_t total=hs+prefix+len;u8 *flat=calloc(1,total);struct rddm_header *h=(void *)flat;h->header_size=hs;h->table_info[0].size=prefix;memset(h->table_info[0].file_name,'X',20);h->table_info[1].size=len;memcpy(h->table_info[1].file_name,"Q6-SFR.bin",11);for(size_t i=0;i<len;i++)flat[hs+prefix+i]='a'+i%26;size_t first=hs+(prefix+len)%9;size_t rest=total-first;unsigned data_entries=1+(rest+6)/7;struct mhi_buf *bufs=calloc(data_entries+1,sizeof(*bufs));bufs[0]=(struct mhi_buf){.buf=flat,.len=first};for(unsigned n=1;n<data_entries;n++){size_t off=first+(n-1)*7;bufs[n]=(struct mhi_buf){.buf=flat+off,.len=min((size_t)7,total-off)};}u8 vector[64]={0};bufs[data_entries]=(struct mhi_buf){.buf=vector,.len=64};struct image_info image={bufs,NULL,data_entries+1};c.rddm_image=&image;reports=0;mhi_dump_sfr(&c);assert(reports==1);assert(strlen(reported)==len+1&&!memcmp(reported,flat+hs+prefix,len)&&reported[len]=='\n');assert(!allocations);h->table_info[0].size=1ULL<<32;reports=0;mhi_dump_sfr(&c);assert(!reports||strncmp(reported,"invalid size",12)==0);h->table_info[0].size=prefix;h->table_info[1].size=U64_MAX;reports=0;mhi_dump_sfr(&c);assert(!reports);free(bufs);free(flat);cases+=3;}
struct rddm_header h={0};struct mhi_buf b[2]={{.buf=&h,.len=sizeof(h)},{.buf=&h,.len=sizeof(h)}};struct image_info image={b,NULL,2};c.rddm_image=&image;u32 bad[]={0,1,7,9,15,UINT_MAX};for(unsigned n=0;n<ARRAY_SIZE(bad);n++){h.header_size=bad[n];mhi_dump_sfr(&c);cases++;}h.header_size=8+sizeof(struct rddm_table_info);memcpy(h.table_info[0].file_name,"Q6-SFR.bin",11);h.table_info[0].size=sizeof(h);reports=0;mhi_dump_sfr(&c);assert(!reports);c.rddm_image=NULL;mhi_dump_sfr(&c);assert(!allocations);printf("{\"segmented_header_and_file_cases\":%u,\"u64_sizes_preserved\":true,\"vector_segment_excluded\":true}\n",cases);}
